import React, { useEffect, useState } from "react";
import axios from "axios";
import "./ActivityLog.css";

const ActivityLog = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchLogs = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://127.0.0.1:8000/api/activity-logs/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setLogs(res.data);
      } catch (err) {
        console.error(err);
        setError("Failed to load activity logs");
      } finally {
        setLoading(false);
      }
    };

    fetchLogs();
  }, []);

  if (loading) return <p>Loading activity logs...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div className="activity-log-container">
      <h2>All User Activity Timeline</h2>
      {logs.length === 0 ? (
        <p>No activity logs found.</p>
      ) : (
        <div className="activity-log-list">
          {logs.map((log, index) => (
            <div className="activity-log-item" key={index}>
              
              {/* Left Section: Avatar + User Info */}
              <div className="log-left">
                <div className="avatar">
                  {log.username ? log.username.charAt(0).toUpperCase() : "U"}
                </div>
                <div className="log-user-info">
                  <span className="log-user">{log.username}</span>
                  <span className="log-email">{log.email || "No Email"}</span>
                </div>
              </div>

              {/* Center Section: Statement + Action */}
              <div className="log-center">
                <div className="log-statement">
                  <strong>Statement:</strong>
                  <div className="log-action-text">
                    {log.action ? log.action.toUpperCase() : "ACTION"} on{" "}
                    {log.model || "Unknown Model"}
                  </div>
                </div>
                <div className="log-details">
                  {log.details?.description || "No additional details"}
                </div>
              </div>

              {/* Right Section: Timestamp */}
              <div className="log-right">
                {new Date(log.timestamp).toLocaleString()}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ActivityLog;
